import{_ as i,C as e,o as s,c as n,j as a,a as l,G as d,a3 as c}from"./chunks/framework.Bvm_liKL.js";const f=JSON.parse('{"title":"手势与快捷操作","description":"ICC-CE 支持的触控手势、笔身按键与常用快捷操作","frontmatter":{"title":"手势与快捷操作","description":"ICC-CE 支持的触控手势、笔身按键与常用快捷操作"},"headers":[],"relativePath":"cn/guide/gestures-shortcuts.md","filePath":"cn/guide/gestures-shortcuts.md"}'),h={name:"cn/guide/gestures-shortcuts.md"};function p(u,t,b,_,m,C){const r=e("ArticleMetadata"),o=e("UnderConstruction");return s(),n("div",null,[t[0]||(t[0]=a("h1",{id:"手势与快捷操作",tabindex:"-1"},[l("手势与快捷操作 "),a("a",{class:"header-anchor",href:"#手势与快捷操作","aria-label":'Permalink to "手势与快捷操作"'},"​")],-1)),d(r),d(o),t[1]||(t[1]=c('<h2 id="触控手势" tabindex="-1">触控手势 <a class="header-anchor" href="#触控手势" aria-label="Permalink to &quot;触控手势&quot;">​</a></h2><p>ICC-CE 的手势系统可以在设置中整体开关，也可以逐项启用。</p><table tabindex="0"><thead><tr><th>手势</th><th>效果</th></tr></thead><tbody><tr><td>单指拖动</td><td>书写（画笔模式下）</td></tr><tr><td>双指捏合 / 张开</td><td>缩放画布</td></tr><tr><td>双指拖动</td><td>平移画布</td></tr><tr><td>双指旋转</td><td>旋转画布（需在设置中启用）</td></tr><tr><td>双指点击</td><td>撤销</td></tr><tr><td>三指点击</td><td>重做</td></tr><tr><td>多指长按</td><td>呼出快捷菜单</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">手势不生效</p><p>先确认设备真的支持多点触控：设备管理器 → 人体学输入设备中应能看到「HID 兼容触摸屏」。 部分老旧一体机的触摸驱动会把双指手势直接吞掉，需要更新为厂商官方驱动。</p></div><h2 id="防误触" tabindex="-1">防误触 <a class="header-anchor" href="#防误触" aria-label="Permalink to &quot;防误触&quot;">​</a></h2><p>书写时手掌搭在屏幕上容易产生杂线。ICC-CE 提供掌压屏蔽功能：</p><ul><li>开启后会自动忽略接触面积过大的触点</li><li>可调整判定阈值，屏幕越大阈值可设得越宽松</li><li>使用主动式电容笔的设备可以直接开启「仅笔书写」，彻底忽略手指输入</li></ul><h2 id="笔身按键" tabindex="-1">笔身按键 <a class="header-anchor" href="#笔身按键" aria-label="Permalink to &quot;笔身按键&quot;">​</a></h2><p>支持的数位笔通常有一到两个侧键，可在设置中分别映射为橡皮擦、选择、撤销等功能。 不少设备把笔尾直接做成橡皮，翻转笔身即可擦除。</p><h2 id="常用快捷操作" tabindex="-1">常用快捷操作 <a class="header-anchor" href="#常用快捷操作" aria-label="Permalink to &quot;常用快捷操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>撤销 / 重做</td><td>工具栏按钮或双指 / 三指点击</td></tr><tr><td>清空画布</td><td>工具栏清空按钮，会进入撤销栈，可以撤销回来</td></tr><tr><td>截屏</td><td>把当前屏幕连同墨迹保存为图片</td></tr><tr><td>切换透明 / 白板模式</td><td>工具栏模式按钮</td></tr><tr><td>收起工具栏</td><td>点击工具栏折叠按钮，书写不受影响</td></tr><tr><td>退出</td><td>工具栏退出按钮，会触发一次自动保存</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">清空与撤销</p><p>清空画布是可撤销的，但退出程序后撤销栈不保留。重要内容请先截屏或等待自动保存完成。</p></div><h2 id="与-powerpoint-放映配合" tabindex="-1">与 PowerPoint 放映配合 <a class="header-anchor" href="#与-powerpoint-放映配合" aria-label="Permalink to &quot;与 PowerPoint 放映配合&quot;">​</a></h2><p>放映时工具栏会额外出现翻页按钮，翻页会自动切换对应页的墨迹。 翻页动作本身不进入撤销栈，详见<a href="/website/cn/guide/ppt-guide">PPT 联动指南</a>。</p>',14))])}const k=i(h,[["render",p]]);export{f as __pageData,k as default};
